@import "@fontsource-variable/inter";
@import "@fontsource-variable/geist-mono";

/* Light (faithful): a cool steel page #eef2f5 with deep navy ink #1c2b44 for text and filled
   buttons, the nav pill a touch deeper (#192738, `secondary`). Lilac-grey hairlines #cfcfdf.
   The only colour is the plasma magenta of the original's WebGL art, kept for `glow` and
   `highlight`. Small radii: 8px media cards (rounded-lg), 6px video frames (rounded-md), 4px
   buttons (rounded-sm). The page's near-black bands carry the `dark` class and use .dark. */
:root {
  --background: #eef2f5;
  --foreground: #1c2b44;
  --card: #ffffff;
  --card-foreground: #0f0f15;
  --popover: #192738;
  --popover-foreground: #eef2f5;
  --primary: #1c2b44;
  --primary-foreground: #eef2f5;
  --secondary: #192738;
  --secondary-foreground: #eef2f5;
  --muted: #d9dee6;
  --muted-foreground: #737d8e;
  --accent: rgb(28 43 68 / 0.07);
  --accent-foreground: #1c2b44;
  --destructive: #c9344a;
  --destructive-foreground: #ffffff;
  --border: #cfcfdf;
  --input: #cfcfdf;
  --ring: #1c2b44;
  --highlight: #f23ff2;
  --highlight-foreground: #0f0f15;
  --glow: #f23ff2;
  --chart-1: #1c2b44;
  --chart-2: #f23ff2;
  --chart-3: #5c7896;
  --chart-4: #a9c3cc;
  --chart-5: #cfcfdf;
  --sidebar: #eef2f5;
  --sidebar-foreground: #1c2b44;
  --sidebar-primary: #1c2b44;
  --sidebar-primary-foreground: #eef2f5;
  --sidebar-accent: rgb(28 43 68 / 0.07);
  --sidebar-accent-foreground: #1c2b44;
  --sidebar-border: #cfcfdf;
  --sidebar-ring: #1c2b44;

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 90rem;
  /* 10px at 390 → 56px at 1440 */
  --page-gutter: clamp(0.625rem, 4.381vw - 0.443rem, 3.5rem);
  /* 113px at 390 → 133px at 1440 */
  --section-y: clamp(7.0625rem, 6.598rem + 1.905vw, 8.3125rem);
}

/* Dark: the original's near-black bands (#0f0f15) with off-white text, white-ish filled
   buttons, #3b3b3b hairlines and a graphite #22262d for the footer's giant wordmark. Its glow
   is the pale steel-blue spotlight of the careers band. Used for the whole page in dark mode
   and for every `dark` band on the light page. */
.dark {
  --background: #0f0f15;
  --foreground: #eef2f5;
  --card: #191b23;
  --card-foreground: #eef2f5;
  --popover: #192738;
  --popover-foreground: #eef2f5;
  --primary: #eef2f5;
  --primary-foreground: #0f0f15;
  --secondary: #192738;
  --secondary-foreground: #eef2f5;
  --muted: #22262d;
  --muted-foreground: #8d95a3;
  --accent: rgb(238 242 245 / 0.08);
  --accent-foreground: #eef2f5;
  --destructive: #ef5c70;
  --destructive-foreground: #0f0f15;
  --border: #3b3b3b;
  --input: #3b3b3b;
  --ring: #eef2f5;
  --highlight: #f23ff2;
  --highlight-foreground: #0f0f15;
  --glow: #bcd9df;
  --chart-1: #eef2f5;
  --chart-2: #f23ff2;
  --chart-3: #bcd9df;
  --chart-4: #5c7896;
  --chart-5: #3b3b3b;
  --sidebar: #0f0f15;
  --sidebar-foreground: #eef2f5;
  --sidebar-primary: #eef2f5;
  --sidebar-primary-foreground: #0f0f15;
  --sidebar-accent: rgb(238 242 245 / 0.08);
  --sidebar-accent-foreground: #eef2f5;
  --sidebar-border: #3b3b3b;
  --sidebar-ring: #eef2f5;
}
